563	    private func readFullThread(session: any ThreadDetailSession) async throws -> FullThreadRead {
564	        let startedAt = Date()
565	        let signpostState = DockSignpost.threadDetail.beginInterval("thread.readFull")
566	        defer {
567	            DockSignpost.threadDetail.endInterval("thread.readFull", signpostState)
568	        }
569	        let readResponse = try await session.threadRead(
570	            params: ThreadReadParams(threadId: row.id.threadID, includeTurns: false),
571	            timeout: CodexDockConstants.AppServer.defaultRequestTimeout
572	        )
573	        let turns = try await readAllTurns(session: session)
574	        DockLog.threadDetail.info("thread full read finished thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) turns=\(turns.count, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
575	        return FullThreadRead(
576	            thread: readResponse.thread.replacingTurns(turns),
577	            turns: turns
578	        )
579	    }
