581	    private func readAllTurns(session: any ThreadDetailSession) async throws -> [JSONValue] {
582	        var cursor: String?
583	        var seenCursors = Set<String>()
584	        var turns: [JSONValue] = []
585	
586	        repeat {
587	            let response = try await session.threadTurnsList(
588	                params: ThreadTurnsListParams(
589	                    threadId: row.id.threadID,
590	                    cursor: cursor,
591	                    limit: Self.turnPageLimit,
592	                    sortDirection: .desc
593	                ),
594	                timeout: CodexDockConstants.AppServer.defaultRequestTimeout
595	            )
596	            turns.append(contentsOf: response.data)
597	
598	            guard let nextCursor = response.nextCursor, !nextCursor.isEmpty else {
599	                cursor = nil
600	                break
601	            }
602	            guard seenCursors.insert(nextCursor).inserted else {
603	                throw ThreadDetailStoreError.repeatedTurnsCursor(nextCursor)
604	            }
605	            cursor = nextCursor
606	        } while cursor != nil
607	
608	        return turns
609	    }
