  9	function parseTimestampMs(value) {
 10	  if (value === null || value === undefined) {
 11	    return null;
 12	  }
 13	  if (typeof value === "number" && Number.isFinite(value)) {
 14	    return value < 10_000_000_000 ? value * 1000 : value;
 15	  }
 16	  if (typeof value === "string" && value.length > 0) {
 17	    const parsed = Date.parse(value);
 18	    return Number.isFinite(parsed) ? parsed : null;
 19	  }
 20	  return null;
 21	}
