 35	function textFromContent(content) {
 36	  if (typeof content === "string") {
 37	    return content;
 38	  }
 39	  if (!Array.isArray(content)) {
 40	    return "";
 41	  }
 42	  return content
 43	    .map((part) => {
 44	      if (typeof part === "string") {
 45	        return part;
 46	      }
 47	      if (!part || typeof part !== "object") {
 48	        return "";
 49	      }
 50	      return part.text || part.content || "";
 51	    })
 52	    .filter(Boolean)
 53	    .join("\n");
 54	}
