 83	func waitForLoadedSnapshot(
 84	    from store: DockStore,
 85	    where predicate: (DockSnapshot) -> Bool,
 86	    timeout: TimeInterval = 2
 87	) async -> DockSnapshot? {
 88	    let deadline = Date().addingTimeInterval(timeout)
 89	    while Date() < deadline {
 90	        if case let .loaded(snapshot) = store.state, predicate(snapshot) {
 91	            return snapshot
 92	        }
 93	        try? await Task.sleep(nanoseconds: 10_000_000)
 94	    }
 95	    return nil
